pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    EtherCartel c;
    function setUp() public { c = new EtherCartel(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        address originalCeo = c.ceoAddress();
        vm.prank(caller);
        (bool ok,) = address(c).call(abi.encodeWithSignature("DrugDealer()"));
        if (ok) {
            assertTrue(c.ceoAddress() == originalCeo);
        } else {
            assertTrue(c.ceoAddress() == originalCeo);
        }
    }
}
